import type { CancerInput, EntityInput, TermInput } from "@/lib/schema";
import type { Spike, SpikeSupplement } from "./index";
import { BREAST, SRC, SUBTYPES, asOf, doi, nice, term } from "./breast-treatment-shared";
import { breastTrialsAxilla, breastTrialsConservation } from "./breast-treatment-trials-surgery";
import { breastTrialsRadiotherapy } from "./breast-treatment-trials-radiotherapy";
import { breastTrialsReconstruction } from "./breast-treatment-trials-reconstruction";

/**
 * BREAST CANCER: THE SHARED TREATMENT SPINE. What happens to nearly everyone with breast cancer whichever
 * receptor result comes back, written on the family page because it is the same on all three subtype pages and
 * should not be written three times: the operation on the breast, the operation on the axilla, radiotherapy,
 * reconstruction, and the choice between giving drugs before or after surgery.
 *
 * What is deliberately not here. The endocrine, anti-HER2 and chemotherapy landscapes belong to the subtype
 * pages and are not repeated: hormone receptor-positive disease in ./breast-hr-positive.ts, HER2-positive in
 * ./breast-her2-positive.ts, triple-negative in ./tnbc-treatment.ts. Where this layer needs to say that drug
 * treatment differs by receptor status, it says so and points at those pages. The NHS pathway, waiting times and
 * services are a separate layer.
 *
 * Facts checked on 25 September 2026 against the primary publications through Europe PMC, the ClinicalTrials.gov
 * version 2 application programming interface and the NICE guidance pages, each quoted with its address. The
 * long-term report of each trial was read rather than the first one, because in breast cancer a five-year
 * equivalence proves very little: hormone receptor-positive disease recurs into the second and third decade, and
 * the conservation and axillary trials only became convincing when they reached twenty and twenty-five years.
 *
 * Three readings of NICE NG101 are worth putting at the top because they surprise people:
 *   - recommendation 1.13.13 makes 26 Gy in five fractions over one week the default whole-breast, partial-breast
 *     or chest-wall schedule in England when the nodes are not being treated;
 *   - recommendation 1.13.16 keeps 40 Gy in fifteen fractions whenever the regional nodes are treated, so the
 *     one-week schedule stops at the edge of the axilla;
 *   - NICE TA501 does not recommend the Intrabeam intraoperative radiotherapy system for routine commissioning,
 *     although TARGIT-A met its non-inferiority margin.
 */

const BREAST_ALL = [BREAST, ...SUBTYPES];

// ======================= GLOSSARY =======================
// Written here because they are the vocabulary of this layer. Each is referenced from a standard-of-care row or a
// trial record above, and each is offered to the family page glossary.
const terms: TermInput[] = [
  term({ id: "breast-conserving-surgery-versus-mastectomy", name: "Breast conservation or mastectomy", category: "Treatment decisions",
    aka: ["lumpectomy versus mastectomy", "breast conservation versus mastectomy", "wide local excision or mastectomy"],
    tldr: "For most early breast cancers, removing the lump with a rim of healthy tissue and then giving radiotherapy leads to exactly the same chance of being alive in twenty years as removing the whole breast. The choice is about the breast, not about survival.",
    summary: "Four randomised trials settled this and all four reported at twenty years or more. NSABP B-06 randomised 1,851 women three ways and found no significant difference in disease-free, distant-disease-free or overall survival between total mastectomy, lumpectomy alone and lumpectomy with irradiation; the hazard ratio for death after lumpectomy with irradiation against mastectomy was 0.97 (95 percent confidence interval 0.83 to 1.14). Milan I randomised 701 women to Halsted radical mastectomy or quadrantectomy with radiotherapy and found death from any cause at twenty years of 41.2 and 41.7 percent (p=1.0). EORTC 10801 randomised 868 patients including tumours up to 5 cm and found time to death at a median 22.1 years no different (hazard ratio 1.11, 0.94 to 1.33). NSABP B-04, at twenty-five years, found no advantage to radical mastectomy over lesser operations at all.\n\nWhat does differ is the chance of the cancer returning in the breast that was kept: 14.3 percent at twenty years in NSABP B-06 with radiotherapy, against 39.2 percent without it, and 8.8 against 2.3 percent between quadrantectomy and radical mastectomy in Milan I. A recurrence in a conserved breast is usually salvageable by mastectomy, which is part of why survival is unaffected: in the EORTC boost trial, mastectomy was the first salvage treatment for 279 of 354 such recurrences (79 percent) in one arm and 178 of 237 (75 percent) in the other.\n\nMastectomy is still the right operation for some: a tumour too large for the breast to give a good result, several tumours in different quadrants, inflammatory breast cancer, a margin that cannot be cleared by re-excision, a woman who cannot have radiotherapy, and a woman who has weighed the options and wants the breast off. Risk-reducing mastectomy in a BRCA1 or BRCA2 carrier is a different operation for a different reason.\n\nIn England NICE NG101 recommendation 1.4.3 offers further surgery when tumour is at the inked margin, and recommendation 1.4.5 considers it when tumour cells lie within 1 mm of the radial margin, a threshold the guideline lowered from 2 mm in 2024 to reduce re-operations.",
    cancers: BREAST_ALL, sections: ["surgery"], related: ["lumpectomy", "mastectomy", "resection-margins", "oncoplastic-breast-surgery", "breast-reconstruction"], trials: ["nsabp-b06", "milan-i", "eortc-10801", "nsabp-b04"],
    links: [doi("NSABP B-06 at twenty years (New England Journal of Medicine 2002)", "10.1056/NEJMoa022152"), doi("Milan I at twenty years (New England Journal of Medicine 2002)", "10.1056/NEJMoa020989"), nice("ng101", "NICE NG101 recommendations 1.4.3 and 1.4.5, surgery to the breast")] }),

  term({ id: "oncoplastic-breast-surgery", name: "Oncoplastic breast surgery", category: "Procedures",
    aka: ["oncoplastic surgery", "therapeutic mammaplasty", "volume displacement", "volume replacement", "oncoplastic breast conservation"],
    tldr: "Techniques borrowed from cosmetic surgery that let a surgeon take out a larger piece of breast and still leave a breast that looks like one, by moving the remaining tissue around or bringing in tissue from nearby.",
    summary: "Oncoplastic techniques divide into volume displacement, where the remaining breast tissue is rearranged to fill the defect, often as a therapeutic mammaplasty that reshapes and lifts both breasts, and volume replacement, where tissue is brought in from the chest wall or back as a local perforator flap. The purpose is to widen the range of tumours that can be treated without mastectomy, and to avoid the deformity that follows a large excision in a small breast.\n\nThe evidence base is a level below the conservation trials, and that is the honest thing to say about it. There is no randomised comparison of oncoplastic conservation against standard conservation, or against mastectomy with reconstruction; what exists is prospective cohorts and registry series. So the case for these techniques rests on the conservation trials for the oncology and on surgical judgement for the appearance, and the costs are known rather than measured: a longer operation, and often a second, unaffected breast operated on to match it.\n\nNICE NG101 refers to oncoplastic repair explicitly in one place, recommendation 1.4.2, which offers breast-conserving surgery with removal of the nipple and areola as an alternative to mastectomy for localised Paget's disease of the nipple and says to offer oncoplastic repair techniques to maximise the cosmetic result.",
    cancers: BREAST_ALL, sections: ["surgery"], related: ["lumpectomy", "mastectomy", "breast-reconstruction", "breast-conserving-surgery-versus-mastectomy", "body-image-after-breast-surgery"],
    links: [nice("ng101", "NICE NG101 recommendation 1.4.2, oncoplastic repair in Paget's disease of the nipple")] }),

  term({ id: "axillary-surgery-de-escalation", name: "Doing less to the armpit", category: "Treatment decisions",
    aka: ["axillary de-escalation", "axillary surgery de-escalation", "omission of axillary dissection", "axillary management"],
    tldr: "Over thirty years surgeons went from clearing every lymph node in the armpit, to taking only the first one or two, to leaving even a cancerous node in place, to not operating on the armpit at all in low-risk cases. At each step the cancer outcome stayed the same and the arm got better.",
    summary: "This is the clearest example in cancer surgery of a field doing less and getting the same result, and it is worth reading as a sequence rather than as a list.\n\nNSABP B-04 showed at twenty-five years that removing occult positive nodes did not save lives. NSABP B-32 randomised 5,611 women with clinically negative nodes and found eight-year overall survival of 90.3 percent with sentinel node biopsy alone against 91.8 percent with added clearance (hazard ratio 1.20, 0.96 to 1.50, p=0.12). ALMANAC measured what that saved: lymphoedema at twelve months fell from 13 to 5 percent and sensory loss from 31 to 11 percent.\n\nThen the field went after the positive node. IBCSG 23-01 found ten-year disease-free survival of 76.8 percent without clearance against 74.9 percent with it for micrometastases, with lymphoedema of 4 against 13 percent. ACOSOG Z0011 found ten-year overall survival of 86.3 against 83.6 percent for one or two positive sentinel nodes after lumpectomy and whole-breast radiotherapy. AMAROS showed radiotherapy to the axilla is an alternative to clearance, with ten-year axillary recurrence of 1.82 against 0.93 percent and lymphoedema halved, 11.9 against 24.5 percent. SENOMAC extended the result to macrometastases, mastectomy and T3 tumours in 2,540 patients, with five-year recurrence-free survival of 89.7 against 88.7 percent.\n\nThen it went after the sentinel node itself. SOUND randomised 1,405 women with tumours up to 2 cm and a clear axillary ultrasound and found five-year distant disease-free survival of 98.0 percent without any axillary surgery against 97.7 percent with sentinel node biopsy. INSEMA randomised 4,858 and found five-year invasive disease-free survival of 91.9 against 91.7 percent, with axillary recurrence of 1.0 against 0.3 percent.\n\nTwo things are still open. POSNOC is the only trial in which the experimental arm receives no axillary treatment at all, radiotherapy included, and it has not reported. And when a woman has no nodal information, the decisions that used to rest on it, whether to give chemotherapy and what radiotherapy fields to use, have to be made from tumour biology instead, which is why SOUND states its condition explicitly: axillary surgery can be spared whenever its absence does not change the postoperative plan.\n\nIn England NICE NG101 recommendation 1.4.9 makes sentinel node biopsy the staging operation, 1.4.14 says not to offer further axillary treatment for micrometastases, 1.4.15 classifies isolated tumour cells as node-negative, and 1.4.13 asks for a discussion of the benefits and risks of no further treatment after one or two macrometastases when whole-breast radiotherapy and systemic therapy are planned.",
    cancers: BREAST_ALL, sections: ["surgery"], technologies: ["sentinel-node"], related: ["sentinel-lymph-node-biopsy", "lymphadenectomy", "breast-cancer-related-lymphoedema", "targeted-axillary-dissection"], trials: ["nsabp-b04", "nsabp-b32", "almanac", "ibcsg-23-01", "acosog-z0011", "amaros", "senomac", "sound", "insema", "posnoc"],
    links: [doi("Locoregional de-escalation trials mapped (npj Breast Cancer 2025)", "10.1038/s41523-025-00744-9"), nice("ng101", "NICE NG101 recommendations 1.4.9 to 1.4.15, surgery to the axilla")] }),

  term({ id: "targeted-axillary-dissection", name: "Targeted axillary dissection", category: "Procedures",
    aka: ["TAD", "clipped node removal", "marked lymph node biopsy", "MARI procedure"],
    tldr: "When chemotherapy is given before surgery, the surgeon marks the lymph node that was known to contain cancer with a clip before treatment starts, then removes that exact node afterwards along with the sentinel nodes. It is the difference between missing leftover cancer one time in ten and one time in fifty.",
    summary: "ACOSOG Z1071 exposed the problem. Among 525 women with biopsy-proven node-positive disease who had two or more sentinel nodes removed after chemotherapy, the sentinel nodes were clear but the axillary clearance was not in 39 cases, a false-negative rate of 12.6 percent against a pre-specified acceptable threshold of 10 percent. Chemotherapy scars and reroutes lymphatics, so the node the tracer reaches after treatment is not reliably the node that was diseased before it.\n\nThe MD Anderson prospective study fixed it by marking the node. Placing a clip in the biopsied node before chemotherapy and localising it at surgery gave a false-negative rate of 4.2 percent for the clipped node alone (95 percent confidence interval 1.4 to 9.5), against 10.1 percent for sentinel node dissection alone (4.2 to 19.8); combining the two brought it to 1.4 percent (0.03 to 7.3, p=0.03), and formal targeted axillary dissection in 85 patients gave 2.0 percent. The finding that justifies the whole technique is that the clipped node was not retrieved as a sentinel node in 23 percent of patients, and six women had negative sentinel nodes but metastasis in the clipped node.\n\nLocalisation is by iodine-125 seed, radiofrequency or magnetic marker, wire, or carbon tattoo, depending on what the unit has. Dual tracer mapping and removing at least three sentinel nodes lower the false-negative rate further.\n\nWhat happens after a clear targeted axillary dissection is the live question. NSABP B-51 has answered the radiotherapy half: regional nodal irradiation adds nothing once the nodes are pathologically clear. ATNEC is asking the surgical half and is still recruiting.",
    cancers: BREAST_ALL, sections: ["surgery"], technologies: ["sentinel-node"], related: ["sentinel-lymph-node-biopsy", "lymphadenectomy", "axillary-surgery-de-escalation", "neoadjuvant-versus-adjuvant-breast"], trials: ["acosog-z1071", "targeted-axillary-dissection-md-anderson", "atnec", "nsabp-b51"],
    links: [doi("Targeted axillary dissection (Journal of Clinical Oncology 2016)", "10.1200/JCO.2015.64.0094"), doi("ACOSOG Z1071 (JAMA 2013)", "10.1001/jama.2013.278932")] }),

  term({ id: "breast-cancer-related-lymphoedema", name: "Lymphoedema after breast cancer treatment", category: "Side effects",
    aka: ["breast cancer-related lymphoedema", "arm lymphoedema", "arm swelling after breast cancer"],
    tldr: "Swelling of the arm, hand or breast that happens when lymph fluid cannot drain because the lymph nodes have been removed or irradiated. It is permanent once established, it can appear years later, and it is the main reason surgeons now take one or two lymph nodes instead of twenty.",
    summary: "The risk is set mostly by what is done to the axilla. Axillary clearance carries the highest risk: in the AMAROS five-year analysis, lymphoedema occurred in 24.5 percent after clearance against 11.9 percent after axillary radiotherapy (p<0.001). In IBCSG 23-01 it was 13 percent with clearance and 4 percent without. In ALMANAC, at twelve months, sentinel node biopsy cut any lymphoedema from 13 to 5 percent (relative risk 0.37, 0.23 to 0.60) and sensory loss from 31 to 11 percent. Omitting the sentinel node entirely lowers it again: INSEMA found less lymphoedema, greater arm mobility and less pain on movement in the group that had no axillary surgery.\n\nRadiotherapy to the axilla and supraclavicular fossa adds to the risk, which is why NICE NG101 recommendation 1.13.20 says not to give axillary radiotherapy after axillary clearance: the two together are the worst combination for the arm. Other risk factors are a higher body mass index, infection in the arm, and the number of nodes removed.\n\nTreatment is decongestive: skin care, compression garments or bandaging, exercise, and manual lymphatic drainage, delivered by a lymphoedema service. Surgical options, lymphovenous anastomosis and vascularised lymph node transfer, exist in specialist centres. The important clinical point is that the swelling can start years after treatment and that early referral matters, because an arm treated early is easier to control than one treated late.\n\nCellulitis in a swollen arm is an emergency of a kind: it needs antibiotics quickly, and each episode makes the lymphoedema worse.",
    cancers: BREAST_ALL, sections: ["surgery"], related: ["lymphadenectomy", "sentinel-lymph-node-biopsy", "axillary-surgery-de-escalation", "lymphoedema-decongestive-therapy"], trials: ["amaros", "almanac", "ibcsg-23-01", "insema"],
    links: [doi("AMAROS ten-year results with five-year morbidity (Journal of Clinical Oncology 2023)", "10.1200/JCO.22.01565"), doi("ALMANAC arm morbidity (Journal of the National Cancer Institute 2006)", "10.1093/jnci/djj158"), nice("ng101", "NICE NG101 recommendation 1.13.20, no axillary radiotherapy after clearance")] }),

  term({ id: "breast-reconstruction", name: "Breast reconstruction", category: "Procedures",
    aka: ["reconstruction after mastectomy", "implant reconstruction", "autologous reconstruction", "DIEP flap", "deep inferior epigastric perforator flap", "tissue expander"],
    tldr: "Rebuilding the shape of a breast after a mastectomy, either with an implant or with the woman's own tissue, at the same operation or years later. In England every woman having a mastectomy for breast cancer must be offered it, and must be offered both timings whether or not the local hospital provides them.",
    summary: "There are two families of technique. Implant-based reconstruction uses a silicone implant, either placed at the mastectomy (direct to implant) or after a tissue expander has stretched the skin, and either behind the pectoralis major (sub-pectoral) or in front of it (pre-pectoral). Autologous reconstruction moves the woman's own skin and fat, most often from the lower abdomen as a deep inferior epigastric perforator flap, which spares the rectus muscle, and less often from the back (latissimus dorsi) or elsewhere. Reconstruction is immediate, at the same operation as the mastectomy, or delayed.\n\nThe honest comparison comes from the Mastectomy Reconstruction Outcomes Consortium, which followed 2,343 women for two years with both complications and a validated patient-reported questionnaire. Autologous reconstruction gave better satisfaction with the breasts (7.94 points higher, 5.68 to 10.20, p<0.001), psychosocial wellbeing and sexual wellbeing at two years. It also roughly doubled the odds of a complication: 1.97 (1.41 to 2.76) for a deep inferior epigastric perforator flap against expander-implant reconstruction. Implants failed more often, 7.1 percent against 1.3 percent for those flaps.\n\nBritish practice has been measured twice and neither reading is comfortable. In iBRA, 2,081 women having immediate implant-based reconstruction at 81 units had implant loss of 9 percent, infection needing treatment of 25 percent, return to theatre of 18 percent and readmission of 18 percent within three months, all above the National Quality Standards of under 5 percent for the first three and under 10 percent for infection. Pre-BRA followed the newer pre-pectoral technique in 343 women and found implant loss of 8.2 percent and a complication in 42.0 percent, with physical and sexual wellbeing significantly below baseline at three and eighteen months.\n\nThe mesh question is unresolved. Biological or synthetic mesh, including acellular dermal matrix, is used to support the implant, and in iBRA 65 percent of reconstructions used it, 54 percent biological and 12 percent synthetic, without randomised evidence that it helps. Best-BRA, a pilot randomised trial of pre-pectoral against sub-pectoral placement, is the attempt to put that right.\n\nOn timing, NICE NG101 recommendation 1.5.1 offers reconstruction to everyone after a mastectomy for breast cancer, 1.5.3 offers both immediate and delayed options whether or not they are available locally, and 1.5.4 offers immediate reconstruction even to women who may need radiotherapy, unless another illness rules out the surgery. The guideline's own table warns that immediate reconstruction using implants may be affected by radiotherapy more than immediate flap reconstruction, and recommendation 1.13.14 allows the three-week radiotherapy schedule rather than the one-week one for women who have had implant-based reconstruction.\n\nBreast implant-associated anaplastic large cell lymphoma is a rare cancer of the capsule around an implant and is covered separately.",
    cancers: BREAST_ALL, sections: ["surgery"], related: ["mastectomy", "oncoplastic-breast-surgery", "bia-alcl", "post-mastectomy-radiotherapy", "body-image-after-breast-surgery"], trials: ["mroc", "ibra-study", "pre-bra", "best-bra", "supremo"],
    links: [nice("ng101", "NICE NG101 recommendations 1.5.1 to 1.5.5, breast reconstruction"), doi("MROC patient-reported outcomes at two years (JAMA Surgery 2018)", "10.1001/jamasurg.2018.1677"), doi("iBRA (Lancet Oncology 2019)", "10.1016/S1470-2045(18)30781-2")] }),

  term({ id: "bia-alcl", name: "Breast implant-associated anaplastic large cell lymphoma", category: "Side effects",
    aka: ["BIA-ALCL", "breast implant-associated lymphoma", "implant-associated ALCL"],
    tldr: "A rare lymphoma that grows in the scar capsule around a breast implant, usually years later, and usually shows itself as sudden swelling of the reconstructed breast from fluid around the implant. It is strongly linked to textured implants, and it is almost always curable by removing the implant and the whole capsule.",
    summary: "The best population estimate comes from the Dutch pathology registry, which identified every primary breast lymphoma between 1990 and 2016. Among 43 patients with breast anaplastic large cell lymphoma, 32 had an implant on the same side, against one of 146 women with other primary breast lymphomas, an odds ratio of 421.8 (95 percent confidence interval 52.6 to 3385.2). The absolute risk is small: the cumulative risk in women with implants was 29 per million at age 50 and 82 per million at 70, and 6,920 women would need an implant to cause one case before the age of 75.\n\nThe implant surface matters. In the Dutch series, 23 of the 28 implants of known type in the lymphoma cases were macrotextured, 82 percent, against 45 percent of implants sold in the same country over 2010 to 2015 (p<0.001). A later meta-analysis across 525,475 patients with implants and 254 cases put the median time from implant to diagnosis at 13.16 years (11.7 to 14.6), found cases almost exclusively with textured implants, and found the same risk whether the implant was placed for reconstruction or for cosmetic reasons. One single-institution series of 3,310 patients exposed only transiently to a textured tissue expander, averaging 6.7 months, followed for a mean 6.8 years, found no cases.\n\nWhat it means in practice. Any late seroma around an implant, typically more than a year after surgery, should be aspirated and the fluid sent for cytology and CD30 immunohistochemistry rather than simply drained. Disease confined to the capsule and treated by complete capsulectomy with implant removal has an excellent outcome; disease that has formed a mass or spread needs systemic treatment. Prevention currently rests on avoiding the exposure, on standardised risk communication and on symptom-driven evaluation rather than on removing implants from women who have no symptoms.",
    cancers: [...BREAST_ALL, "male-breast-cancer"], sections: ["surgery"], related: ["breast-reconstruction", "mastectomy"], trials: ["ibra-study"],
    links: [doi("Breast implants and the risk of anaplastic large-cell lymphoma (JAMA Oncology 2018)", "10.1001/jamaoncol.2017.4510"), doi("Risk of BIA-ALCL, systematic review and meta-analysis (Aesthetic Plastic Surgery 2024)", "10.1007/s00266-024-03956-9"), doi("Genetic susceptibility and current prevention guidance in BIA-ALCL (Biomedicines 2026)", "10.3390/biomedicines14030600"), doi("No cases after transient exposure to a textured tissue expander, 3,310 patients (Plastic and Reconstructive Surgery 2023)", "10.1097/PRS.0000000000010195")] }),

  term({ id: "radiotherapy-omission-early-breast-cancer", name: "Leaving radiotherapy out", category: "Treatment decisions",
    aka: ["radiotherapy omission", "omitting breast radiotherapy", "de-escalation of radiotherapy"],
    tldr: "Radiotherapy after breast-conserving surgery halves the chance of the cancer coming back and prevents about one death in breast cancer for every four recurrences it prevents. In older women with small, hormone-sensitive, slow-growing tumours who will take endocrine therapy, the recurrence risk is so low to start with that leaving radiotherapy out changes almost nothing.",
    summary: "The size of the benefit was measured once and definitively. The Early Breast Cancer Trialists' Collaborative Group pooled individual data for 10,801 women in 17 randomised trials of radiotherapy against none after breast-conserving surgery. Radiotherapy cut the ten-year risk of any first recurrence from 35.0 to 19.3 percent (absolute reduction 15.7 percent) and the fifteen-year risk of death from breast cancer from 25.2 to 21.4 percent (absolute reduction 3.8 percent). The relationship that lets the benefit be predicted is the one the overview named: about one breast cancer death is avoided by year fifteen for every four recurrences avoided by year ten. The proportional benefit varies little between groups of women; the absolute benefit varies a great deal, and can be predicted before treatment from age, grade, oestrogen receptor status, tamoxifen use and the extent of surgery.\n\nThree trials found the group in whom the absolute benefit is small enough to discuss omitting. CALGB 9343 randomised 636 women aged 70 or over with stage I oestrogen receptor-positive disease on tamoxifen and found ten-year locoregional recurrence of 10 percent without radiotherapy against 2 percent with it, and no difference in mastectomy rates, distant disease or survival. PRIME II randomised 1,326 women aged 65 or over with node-negative hormone receptor-positive tumours up to 3 cm and found ten-year local recurrence of 9.5 against 0.9 percent with no difference in survival. LUMINA took 500 women aged 55 or over with grade 1 or 2 T1N0 luminal A disease, selected by biology rather than age alone, and found five-year local recurrence of 2.3 percent without radiotherapy.\n\nIn England the rule is written down. NICE NG101 recommendation 1.13.7 considers not using radiotherapy for women aged 65 and over with clear margins and a very low absolute risk of local recurrence, defined as T1N0, oestrogen receptor-positive, HER2-negative, grade 1 to 2, who are willing to take endocrine therapy for at least five years. Recommendation 1.13.8 says what has to be explained: without radiotherapy, local recurrence occurs in about 50 women per 1,000 at five years, and with it in about 10 per 1,000; overall survival at ten years is the same either way; and in this low-risk group there is no increase in serious late effects such as heart failure, heart attack or second cancer from having radiotherapy.\n\nThe corollary is the one that gets lost. Omission is an option for a narrow group, defined by age, size, grade, receptor status and a commitment to endocrine therapy. Outside that group radiotherapy after breast conservation is standard, and NICE NG101 recommendation 1.13.3 offers it to every woman with invasive cancer and clear margins.",
    cancers: BREAST_ALL, sections: ["radiation"], technologies: ["imrt-igrt"], related: ["hypofractionation", "partial-breast-irradiation", "lumpectomy", "tumour-bed-boost"], trials: ["calgb-9343", "prime-ii", "lumina", "nsabp-b06"],
    links: [doi("EBCTCG: radiotherapy after breast-conserving surgery, 10,801 women in 17 trials (The Lancet 2011)", "10.1016/S0140-6736(11)61629-2"), nice("ng101", "NICE NG101 recommendations 1.13.3, 1.13.7 and 1.13.8, radiotherapy after breast-conserving surgery")] }),

  term({ id: "partial-breast-irradiation", name: "Partial-breast irradiation", category: "Treatment jargon",
    aka: ["accelerated partial breast irradiation", "APBI", "partial breast radiotherapy", "tumour bed irradiation"],
    tldr: "Treating only the part of the breast around where the lump was, instead of the whole breast, on the grounds that almost all recurrences happen there. It works, but which schedule is used decides whether the breast looks better or worse afterwards.",
    summary: "Four randomised trials tested the idea and the disagreement between them is about delivery, not about the target.\n\nIMPORT LOW randomised 2,018 women to whole-breast radiotherapy, whole-breast with reduced dose outside the tumour bed, or partial-breast treatment only, all 40 Gy in fifteen fractions using ordinary tangential fields simply shortened. Five-year local relapse was 0.5 percent with partial-breast treatment against 1.1 percent with whole-breast, non-inferior, with fewer reported changes in breast appearance. RAPID randomised 2,135 women to 38.5 Gy in ten fractions given twice a day: the eight-year recurrence rate was non-inferior at 3.0 against 2.8 percent, but late grade 2 or worse toxicity was 32 against 13 percent and adverse cosmesis was 17.7 percentage points more common at seven years. NSABP B-39/RTOG 0413 randomised 4,216 women to twice-daily partial-breast treatment by brachytherapy or external beam and found ten-year recurrence of 4.6 against 3.9 percent, a small absolute difference whose confidence interval crossed the equivalence margin, so equivalence was not established. TARGIT-A gave a single dose during the operation itself and met its non-inferiority margin, with five-year local recurrence of 2.11 against 0.95 percent.\n\nThe pattern is that once-daily external beam partial-breast treatment matches whole-breast treatment on both cancer control and appearance, while twice-daily schedules match on cancer control and lose on appearance. That is why NICE NG101 recommendation 1.13.6 says to use external beam radiotherapy when giving partial-breast treatment.\n\nEngland restricts who is offered it. NICE NG101 recommendation 1.13.4 considers partial-breast radiotherapy for women who have had breast-conserving surgery for invasive cancer excluding lobular type, with clear margins, a low absolute risk of local recurrence defined as aged 50 or over with tumours of 3 cm or less, node-negative, oestrogen receptor-positive, HER2-negative and grade 1 to 2, and who will take endocrine therapy for at least five years. Recommendation 1.13.5 requires the discussion to say that five-year local recurrence is equivalent to whole-breast treatment, that the risk beyond five years is not yet known, and that late adverse effects may be fewer. Intraoperative radiotherapy is separately not recommended for routine commissioning by NICE TA501.\n\nAn open problem has appeared since the axillary de-escalation trials reported: every partial-breast trial required pathological nodal staging as part of its eligibility, and women who now have no sentinel node biopsy therefore fall outside the evidence.",
    cancers: [...BREAST_ALL, "ductal-carcinoma-in-situ"], sections: ["radiation"], technologies: ["imrt-igrt", "hdr-brachytherapy", "intraoperative-radiotherapy"], related: ["hypofractionation", "radiotherapy-omission-early-breast-cancer", "tumour-bed-boost"], trials: ["import-low", "rapid", "nsabp-b39", "targit-a"],
    links: [nice("ng101", "NICE NG101 recommendations 1.13.4 to 1.13.6, partial-breast radiotherapy"), nice("ta501", "NICE TA501: Intrabeam, not recommended for routine commissioning"), doi("RAPID (The Lancet 2019)", "10.1016/S0140-6736(19)32515-2")] }),

  term({ id: "tumour-bed-boost", name: "Tumour bed boost", category: "Treatment jargon",
    aka: ["boost", "breast boost", "radiotherapy boost", "boost to the tumour bed"],
    tldr: "An extra dose of radiotherapy aimed at the small area the lump came from, given after the whole breast has been treated. It cuts the chance of the cancer coming back in that breast by about a third, does not help anyone live longer, and triples the chance of the breast becoming hard and scarred.",
    summary: "EORTC 22881-10882 randomised 5,318 patients after complete excision and 50 Gy of whole-breast irradiation to a further 16 Gy to the tumour bed or to nothing more, and followed them for a median 17.2 years. Twenty-year overall survival was 59.7 percent with the boost and 61.1 percent without (hazard ratio 1.05, 99 percent confidence interval 0.92 to 1.19, p=0.323). The twenty-year cumulative incidence of recurrence in the treated breast was 12.0 percent with the boost against 16.4 percent without (hazard ratio 0.65, 0.52 to 0.81, p<0.0001). Severe fibrosis at twenty years was 5.2 percent with the boost against 1.8 percent without (p<0.0001).\n\nThe trial's own reading of its data is that the absolute benefit is largest in young patients and that the extra dose can be avoided in most patients over 60, because the recurrence risk they start from is low enough that a one-third reduction saves few events while the fibrosis is the same for everyone.\n\nNICE NG101 recommendation 1.13.17 offers an external beam boost to women with invasive breast cancer and a high risk of local recurrence following whole-breast radiotherapy, and 1.13.18 requires that the risk of side effects be explained. Neither recommendation defines high risk numerically, so the judgement is local and usually rests on age, grade, margin width and lymphovascular invasion.",
    cancers: BREAST_ALL, sections: ["radiation"], technologies: ["imrt-igrt"], related: ["partial-breast-irradiation", "resection-margins", "hypofractionation", "lumpectomy"], trials: ["eortc-22881-boost", "eortc-10801"],
    links: [doi("EORTC boost trial at twenty years (Lancet Oncology 2015)", "10.1016/S1470-2045(14)71156-8"), nice("ng101", "NICE NG101 recommendations 1.13.17 and 1.13.18, breast boost")] }),

  term({ id: "post-mastectomy-radiotherapy", name: "Radiotherapy after mastectomy", category: "Treatment jargon",
    aka: ["postmastectomy radiotherapy", "PMRT", "chest wall radiotherapy", "chest-wall irradiation"],
    tldr: "Radiotherapy to the chest wall, and often the nearby lymph node areas, after the breast has been removed. It clearly helps women with cancer in several lymph nodes. For women with one to three involved nodes treated with modern drugs, a trial that reported in 2025 found it did not lengthen life.",
    summary: "The classic evidence is the Early Breast Cancer Trialists' Collaborative Group overview of 8,135 women randomised in 22 trials between 1964 and 1986. Among 700 women with clear nodes after axillary dissection, radiotherapy did nothing to locoregional recurrence, overall recurrence (rate ratio 1.06, 0.76 to 1.48) or breast cancer mortality (1.18, 0.89 to 1.55). Among 1,314 women with one to three positive nodes it reduced locoregional recurrence, overall recurrence (rate ratio 0.68, 0.57 to 0.82) and breast cancer mortality (0.80, 0.67 to 0.95), and the same held in the 1,133 who received systemic therapy in both arms. Among 1,772 women with four or more positive nodes it reduced overall recurrence (0.79, 0.69 to 0.90) and breast cancer mortality (0.87, 0.77 to 0.99).\n\nThose trials predate anthracyclines, taxanes, aromatase inhibitors and trastuzumab, and the overview says so: for today's women the absolute gains might be smaller, although the proportional gains might be larger because the radiotherapy itself is better. SUPREMO was designed to settle it in the modern era, and reported in 2025. Among 1,607 patients with intermediate-risk disease, defined as pT1N1, pT2N1, pT3N0 or pT2N0 with grade 3 histology or lymphovascular invasion, ten-year overall survival was 81.4 percent with chest-wall irradiation and 81.9 percent without (hazard ratio 1.04, 0.82 to 1.30, p=0.80). Chest-wall recurrence was 1.1 against 2.5 percent (hazard ratio 0.45, 0.20 to 0.99), so the treatment worked and the disease it prevents is simply rare.\n\nSUPREMO tested chest-wall irradiation alone and not comprehensive nodal irradiation, so it does not answer the nodal question, and its accrual was long and its eligibility widened part way through. That is why commentary since has drawn opposite conclusions from the same paper.\n\nIn England NICE NG101 recommendation 1.13.10 offers postmastectomy radiotherapy to people with node-positive macrometastatic disease or involved margins, 1.13.11 considers it for node-negative T3 or T4 disease, and 1.13.12 says not to offer it to people at low risk of local recurrence, for example most people who are node-negative. Recommendations 1.13.26 to 1.13.29 carry the same logic across to patients treated with chemotherapy before surgery, and the guideline predates both SUPREMO and NSABP B-51.",
    cancers: BREAST_ALL, sections: ["radiation"], technologies: ["imrt-igrt", "hypofractionated-radiotherapy"], related: ["mastectomy", "breast-reconstruction", "hypofractionation", "radiotherapy-omission-early-breast-cancer"], trials: ["supremo", "nsabp-b51", "ma-20", "eortc-22922", "nsabp-b04"],
    links: [doi("EBCTCG: radiotherapy after mastectomy, 8,135 women in 22 trials (The Lancet 2014)", "10.1016/S0140-6736(14)60488-8"), doi("SUPREMO ten-year survival (New England Journal of Medicine 2025)", "10.1056/NEJMoa2412225"), nice("ng101", "NICE NG101 recommendations 1.13.10 to 1.13.12, radiotherapy after mastectomy")] }),

  term({ id: "neoadjuvant-versus-adjuvant-breast", name: "Drugs before or after the operation", category: "Treatment decisions",
    aka: ["neoadjuvant versus adjuvant breast cancer", "primary systemic therapy", "preoperative chemotherapy in breast cancer"],
    tldr: "Giving the same drugs before surgery rather than after does not change how long a woman lives, but it shrinks the tumour so that more women keep their breast, and it shows whether the drugs worked, which now decides what treatment comes next.",
    summary: "The survival question was answered by the Early Breast Cancer Trialists' Collaborative Group, pooling individual data for 4,756 women in ten randomised trials that compared the same chemotherapy given before or after surgery. More than two thirds of women given chemotherapy first had a complete or partial clinical response, and breast-conserving therapy was performed in 65 percent of them against 49 percent of those treated after surgery. There was no significant difference in distant recurrence at fifteen years (38.2 against 38.0 percent), breast cancer mortality (34.4 against 33.7 percent) or death from any cause (40.9 against 41.2 percent).\n\nThere is a cost, and it is local. Fifteen-year local recurrence was 21.4 percent after chemotherapy given first against 15.9 percent after surgery first, an absolute increase of 5.5 percent (rate ratio 1.37, 1.17 to 1.61, p=0.0001). The overview's explanation is that a tumour shrunk by chemotherapy may recur more often after conservation than a tumour of the same measured size that was never shrunk, and its recommendation is careful tumour localisation, detailed pathological assessment and appropriate radiotherapy rather than a retreat from the strategy.\n\nWhat has changed since those trials is the second reason to treat first, which they were not designed to measure: the response itself is information. Whether cancer remains in the breast and nodes at surgery now decides what is given afterwards, and that decision differs by receptor subtype, so it belongs on the subtype pages rather than here. The axillary and radiotherapy consequences are shared and are covered here: targeted axillary dissection for staging the axilla afterwards, ACOSOG Z1071 for why marking the node is necessary, and NSABP B-51, which found that regional nodal irradiation adds nothing once the nodes are pathologically clear.\n\nIn England NICE NG101 recommendations 1.13.25 to 1.13.29 govern radiotherapy after chemotherapy given first, and they key the decision to both the pretreatment stage and the post-treatment pathology.",
    cancers: BREAST_ALL, sections: ["surgery", "radiation"], related: ["neoadjuvant-adjuvant", "targeted-axillary-dissection", "pcr", "rcb", "breast-conserving-surgery-versus-mastectomy"], trials: ["nsabp-b51", "acosog-z1071", "targeted-axillary-dissection-md-anderson", "atnec"],
    links: [doi("EBCTCG: chemotherapy before or after surgery, 4,756 women in ten trials (Lancet Oncology 2018)", "10.1016/S1470-2045(17)30777-5"), nice("ng101", "NICE NG101 recommendations 1.13.25 to 1.13.29, radiotherapy after neoadjuvant chemotherapy")] }),
];

