// Only what is the same whichever receptor result comes back. Where a row would have to name a drug, it points at
// the subtype page instead.
const breastStandardOfCare: NonNullable<CancerInput["standardOfCare"]> = [
  { setting: "Surgery to the breast: conservation or mastectomy", approach: "Breast-conserving surgery with radiotherapy, or mastectomy, depending on the size of the tumour against the size of the breast, whether there is more than one tumour, whether radiotherapy is possible, and what the woman wants. Survival is the same either way and has been for twenty years: NSABP B-06 found a hazard ratio for death of 0.97 (0.83 to 1.14) for lumpectomy with irradiation against mastectomy, Milan I found death from any cause of 41.7 against 41.2 percent at twenty years, and EORTC 10801 found a hazard ratio of 1.11 (0.94 to 1.33) at a median 22.1 years. What differs is recurrence in the conserved breast, which is why radiotherapy goes with conservation. Oncoplastic techniques widen the range of tumours that can be conserved.", refs: ["nsabp-b06", "milan-i", "eortc-10801", "nsabp-b04", "lumpectomy", "mastectomy", "breast-conserving-surgery-versus-mastectomy", "oncoplastic-breast-surgery"], guideline: { version: "NICE NG101 recommendations 1.4.1 to 1.4.6", url: SRC.ng101 } },

  { setting: "Margins and further surgery", approach: "Re-excision or mastectomy when tumour reaches the inked margin. NICE NG101 recommendation 1.4.3 offers further surgery when invasive cancer or ductal carcinoma in situ is present at the radial margin (0 mm), and recommendation 1.4.5, new in 2024, considers it when tumour cells lie within 1 mm of but not at the radial margin. The threshold for invasive cancer was lowered from 2 mm to 1 mm because the evidence could not separate 1 to 2 mm from more than 2 mm on local recurrence, and repeated operations harm appearance and self-image. For ductal carcinoma in situ alone the 2 mm threshold is retained (recommendation 1.4.4).", refs: ["resection-margins", "lumpectomy", "ductal-carcinoma-in-situ", "breast-conserving-surgery-versus-mastectomy"], guideline: { version: "NICE NG101 recommendations 1.4.3 to 1.4.6", url: SRC.ng101 } },

  { setting: "Staging the axilla when the nodes look clear", approach: "Sentinel lymph node biopsy, not axillary clearance, with dual technique using isotope and blue dye (NICE NG101 recommendations 1.4.9 and 1.4.10). NSABP B-32 randomised 5,611 women and found eight-year overall survival of 90.3 percent with sentinel node biopsy alone against 91.8 percent with added clearance (hazard ratio 1.20, 0.96 to 1.50); ALMANAC measured the gain, with lymphoedema at one year falling from 13 to 5 percent and sensory loss from 31 to 11 percent. In selected patients the sentinel node itself can now be omitted: SOUND (tumours up to 2 cm, clear axillary ultrasound) and INSEMA (T1 and T2, breast-conserving surgery) both showed non-inferiority, with axillary recurrence in INSEMA of 1.0 against 0.3 percent. Omission is only reasonable where the missing nodal information would not change the treatment plan.", refs: ["nsabp-b32", "almanac", "sound", "insema", "sentinel-lymph-node-biopsy", "sentinel-node", "axillary-surgery-de-escalation"], guideline: { version: "NICE NG101 recommendations 1.4.9 and 1.4.10", url: SRC.ng101 } },

  { setting: "A positive sentinel node", approach: "Isolated tumour cells count as node-negative and need nothing further (NICE NG101 recommendation 1.4.15). Micrometastases need nothing further either: IBCSG 23-01 found ten-year disease-free survival of 76.8 percent without clearance against 74.9 percent with it, and lymphoedema of 4 against 13 percent (recommendation 1.4.14). For one or two macrometastases, NICE recommendation 1.4.12 offers axillary clearance or axillary radiotherapy and recommendation 1.4.13 asks for a discussion of having neither after breast-conserving surgery with whole-breast radiotherapy and systemic therapy. The evidence behind that discussion is Z0011 (ten-year overall survival 86.3 against 83.6 percent) and SENOMAC (five-year recurrence-free survival 89.7 against 88.7 percent in 2,540 patients including mastectomy and T3 disease). Where the axilla is treated, AMAROS makes radiotherapy the gentler choice: ten-year axillary recurrence of 1.82 against 0.93 percent, with lymphoedema halved at 11.9 against 24.5 percent.", refs: ["acosog-z0011", "senomac", "amaros", "ibcsg-23-01", "posnoc", "lymphadenectomy", "breast-cancer-related-lymphoedema", "axillary-surgery-de-escalation"], guideline: { version: "NICE NG101 recommendations 1.4.11 to 1.4.15", url: SRC.ng101 } },

  { setting: "The axilla after chemotherapy given before surgery", approach: "Sentinel node biopsy after chemotherapy is unreliable on its own: ACOSOG Z1071 found a false-negative rate of 12.6 percent against a pre-specified threshold of 10 percent. The fix is targeted axillary dissection, marking the biopsied node before chemotherapy and removing that node as well as the sentinel nodes, which brought the false-negative rate to 1.4 percent when combined with sentinel node dissection and 2.0 percent as a formal procedure. If the nodes are pathologically clear afterwards, NSABP B-51 found that regional nodal irradiation adds nothing (hazard ratio 0.88, 0.60 to 1.28, p=0.51). Whether axillary surgery can also be dropped in that situation is what ATNEC is recruiting to answer.", refs: ["acosog-z1071", "targeted-axillary-dissection-md-anderson", "nsabp-b51", "atnec", "targeted-axillary-dissection", "neoadjuvant-versus-adjuvant-breast"], guideline: { version: "NICE NG101 recommendations 1.13.26 to 1.13.29", url: SRC.ng101 } },

  { setting: "Radiotherapy after breast-conserving surgery", approach: "Whole-breast radiotherapy for every woman with invasive cancer and clear margins (NICE NG101 recommendation 1.13.3). The Early Breast Cancer Trialists' Collaborative Group overview of 10,801 women in 17 trials found radiotherapy cut the ten-year risk of any first recurrence from 35.0 to 19.3 percent and the fifteen-year risk of breast cancer death from 25.2 to 21.4 percent, with about one death avoided by year fifteen for every four recurrences avoided by year ten. A boost of 16 Gy to the tumour bed is offered where the risk of local recurrence is high (recommendation 1.13.17): EORTC 22881-10882 found twenty-year recurrence of 12.0 against 16.4 percent with no survival gain and severe fibrosis of 5.2 against 1.8 percent.", refs: ["nsabp-b06", "eortc-22881-boost", "tumour-bed-boost", "imrt-igrt", "radiotherapy-omission-early-breast-cancer"], guideline: { version: "NICE NG101 recommendations 1.13.3 and 1.13.17", url: SRC.ng101 } },

  { setting: "Dose and schedule", approach: "In England, 26 Gy in five fractions over one week for partial-breast, whole-breast or chest-wall radiotherapy without nodal irradiation (NICE NG101 recommendation 1.13.13), and 40 Gy in fifteen fractions over three weeks when the regional nodes are treated (recommendation 1.13.16) or where a diagnosis increases radiosensitivity, an implant-based reconstruction has been done, or a three-week course is simply more acceptable (recommendation 1.13.14). The radiobiology came from three British trials: START-A held the treatment time constant and varied the fraction size, START-B established 40 Gy in fifteen, FAST estimated the alpha to beta ratio at 2.7 Gy and so predicted a five-fraction equivalent of 28 Gy, and FAST-Forward tested 26 Gy in five fractions in 4,096 women and found five-year recurrence of 1.4 against 2.1 percent. Deep inspiratory breath hold is used for left-sided cancers to lower the heart dose (recommendation 1.13.2), because major coronary events rise by 7.4 percent per gray of mean heart dose with no threshold.", refs: ["start-a", "start-b", "fast-trial", "fast-forward", "hypofractionated-radiotherapy", "hypofractionation", "deep-inspiration-breath-hold", "alpha-beta-ratio"], guideline: { version: "NICE NG101 recommendations 1.13.1, 1.13.2, 1.13.13, 1.13.14 and 1.13.16", url: SRC.ng101 } },

  { setting: "Treating less than the whole breast", approach: "Partial-breast radiotherapy is considered for women who have had breast-conserving surgery for invasive cancer excluding lobular type, with clear margins, aged 50 or over with tumours of 3 cm or less, node-negative, oestrogen receptor-positive, HER2-negative, grade 1 to 2, who will take endocrine therapy for at least five years, and it must be given by external beam (NICE NG101 recommendations 1.13.4 to 1.13.6). IMPORT LOW found five-year local relapse of 0.5 against 1.1 percent with fewer changes in breast appearance, while RAPID, which gave the dose twice a day, was non-inferior on recurrence but had late toxicity of 32 against 13 percent. Intraoperative radiotherapy during the lumpectomy met its non-inferiority margin in TARGIT-A and had lower mortality from causes other than breast cancer (hazard ratio 0.59, 0.40 to 0.86), but NICE TA501 does not recommend the Intrabeam system for routine commissioning and permits it only on existing machines under NHS England governance.", refs: ["import-low", "rapid", "nsabp-b39", "targit-a", "partial-breast-irradiation", "intraoperative-radiotherapy"], guideline: { version: "NICE NG101 recommendations 1.13.4 to 1.13.6; NICE TA501 (not recommended for routine commissioning)", url: SRC.ta501 } },

  { setting: "Who can leave radiotherapy out", approach: "Women aged 65 and over with clear margins and a very low absolute risk of local recurrence, defined by NICE NG101 recommendation 1.13.7 as T1N0, oestrogen receptor-positive, HER2-negative, grade 1 to 2, who are willing to take endocrine therapy for at least five years. Recommendation 1.13.8 sets out what must be said: without radiotherapy local recurrence occurs in about 50 women per 1,000 at five years and with it in about 10 per 1,000; overall survival at ten years is the same; and there is no increase in serious late effects from having it in this group. CALGB 9343 (aged 70 and over, ten-year locoregional recurrence 10 against 2 percent), PRIME II (aged 65 and over, ten-year local recurrence 9.5 against 0.9 percent) and LUMINA (aged 55 and over with luminal A biology, five-year local recurrence 2.3 percent) are the trials behind it. Outside that group radiotherapy after conservation remains standard.", refs: ["calgb-9343", "prime-ii", "lumina", "radiotherapy-omission-early-breast-cancer", "active-surveillance"], guideline: { version: "NICE NG101 recommendations 1.13.7 and 1.13.8", url: SRC.ng101 } },

  { setting: "Radiotherapy after mastectomy, and to the nodes", approach: "Chest-wall radiotherapy is offered for node-positive macrometastatic disease or involved margins (NICE NG101 recommendation 1.13.10), considered for node-negative T3 or T4 disease (1.13.11) and not offered to people at low risk of local recurrence (1.13.12). SUPREMO tested it in intermediate-risk disease treated with modern systemic therapy and found ten-year overall survival of 81.4 against 81.9 percent (hazard ratio 1.04, p=0.80), with chest-wall recurrence of 1.1 against 2.5 percent. For the nodes: no regional nodal radiotherapy for histologically node-negative disease (1.13.19), no axillary radiotherapy after axillary clearance because the combination is the worst for the arm (1.13.20), supraclavicular fossa radiotherapy for four or more involved nodes (1.13.21) or for one to three with other poor prognostic factors (1.13.22), and the internal mammary chain considered within the nodal target for macrometastatic node-positive disease (1.13.23). MA.20 and EORTC 22922 are the trials behind nodal irradiation.", refs: ["supremo", "ma-20", "eortc-22922", "nsabp-b51", "post-mastectomy-radiotherapy", "mastectomy"], guideline: { version: "NICE NG101 recommendations 1.13.10 to 1.13.12 and 1.13.19 to 1.13.23", url: SRC.ng101 } },

  { setting: "Reconstruction", approach: "Reconstruction is offered to everyone having a mastectomy for breast cancer, and both timings, immediate and delayed, are offered whether or not they are available locally (NICE NG101 recommendations 1.5.1 and 1.5.3). Immediate reconstruction is offered even where radiotherapy is planned, unless other illness rules out the surgery (1.5.4). The choice between an implant and the woman's own tissue is a real trade: in the Mastectomy Reconstruction Outcomes Consortium, autologous reconstruction gave higher satisfaction with the breasts at two years (7.94 points, 5.68 to 10.20) but roughly double the odds of a complication, while implants failed more often (7.1 against 1.3 percent). British outcomes after implant reconstruction have been measured and are above the national standards: iBRA found implant loss of 9 percent, infection of 25 percent and return to theatre of 18 percent within three months across 81 units, and Pre-BRA found implant loss of 8.2 percent for the newer pre-pectoral technique. Mesh was used in 65 percent of iBRA reconstructions without randomised evidence; Best-BRA is the pilot trial testing implant placement properly.", refs: ["mroc", "ibra-study", "pre-bra", "best-bra", "breast-reconstruction", "bia-alcl", "mastectomy"], guideline: { version: "NICE NG101 recommendations 1.5.1 to 1.5.5", url: SRC.ng101 } },

  { setting: "Drugs before or after surgery", approach: "Which drugs are given is decided by receptor status and belongs on the subtype pages; when they are given is shared. The Early Breast Cancer Trialists' Collaborative Group pooled 4,756 women in ten trials of the same chemotherapy before or after surgery and found no difference in distant recurrence (38.2 against 38.0 percent at fifteen years), breast cancer mortality or death from any cause, with breast conservation achieved in 65 against 49 percent and fifteen-year local recurrence higher after chemotherapy first (21.4 against 15.9 percent, rate ratio 1.37). Treating first is chosen to make conservation possible, to make a large or node-positive tumour operable, and to see whether the drugs work, because what remains at surgery now guides what follows, differently for each receptor subtype.", refs: ["neoadjuvant-versus-adjuvant-breast", "neoadjuvant-adjuvant", "breast-hr-positive", "breast-her2-positive", "tnbc", "pcr", "rcb"], guideline: { version: "NICE NG101 recommendations 1.13.25 to 1.13.29; EBCTCG meta-analysis of ten trials", url: SRC.ebctcgNeoadjuvant } },
];

